static void inventory_refusal(CohRepReader r){CohRepReader before=r;memset(inventory,0xa5,sizeof(*inventory));*inventory_prior=*inventory;CHECK(coh_inventory_update_read(&r,inventory,inventory_workspace,COH_INVENTORY_RAM_MAX,0)!=COH_OK);CHECK(!memcmp(&before,&r,sizeof(r))&&!memcmp(inventory,inventory_prior,sizeof(*inventory)));}
static void invention_refusal(CohRepReader r){CohRepReader before=r;memset(invention,0xa5,sizeof(*invention));*invention_prior=*invention;CHECK(coh_invention_update_read(&r,invention,invention_workspace,COH_INVENTION_RAM_MAX,0)!=COH_OK);CHECK(!memcmp(&before,&r,sizeof(r))&&!memcmp(invention,invention_prior,sizeof(*invention)));}
static void phase_refusal(CohRepReader r,CohStatus expected){CohRepReader before=r;memset(phase,0xa5,sizeof(*phase));*phase_prior=*phase;CohStatus s=coh_inventory_phase_read(&r,phase,phase_workspace,COH_INVENTORY_PHASE_RAM_MAX,0);CHECK(s!=COH_OK);if(expected!=COH_OK)CHECK(s==expected);CHECK(!memcmp(&before,&r,sizeof(r))&&!memcmp(phase,phase_prior,sizeof(*phase)));}
static void bitcopy(uint8_t*d,size_t offset,const uint8_t*s,size_t begin,size_t end){for(size_t b=begin;b<end;b++){uint8_t m=(uint8_t)(1u<<((offset+b-begin)%8));if(s[b/8]&(1u<<(b%8)))d[(offset+b-begin)/8]|=m;else d[(offset+b-begin)/8]&=(uint8_t)~m;}}
